          pt: "Google Health API e Google Fit APIs para desenvolvedores",
          fr: "Google Health API et Google Fit APIs pour les developpeurs",
          pl: "Google Health API i Google Fit APIs dla programistow",
          tr: "Gelistiriciler icin Google Health API ve Google Fit APIs",
          nl: "Google Health API en Google Fit API's voor ontwikkelaars",
          ja: "\u958b\u767a\u8005\u5411\u3051Google Health API\u3068Google Fit APIs",
          ko: "\uac1c\ubc1c\uc790\ub97c \uc704\ud55c Google Health API\uc640 Google Fit APIs",
