      text: {
          it: "Perché Google Health può non aggiornarsi da Health Connect",
          en: "Why Google Health may not update from Health Connect",
          es: "Por qué Google Health puede no actualizarse desde Health Connect",
          de: "Warum Google Health sich möglicherweise nicht von Health Connect aktualisiert",
          pt: "Por que o Google Saúde pode não atualizar a partir do Health Connect",
          fr: "Pourquoi Google Health peut ne pas se mettre à jour depuis Health Connect",
          pl: "Dlaczego Google Health może się nie aktualizować z Health Connect",
          tr: "Google Health neden Health Connect'ten güncellenmeyebilir",
          nl: "Waarom Google Health mogelijk niet bijwerkt vanuit Health Connect",
          ja: "Google Health が Health Connect から更新されない理由",
          ko: "Google Health가 Health Connect에서 업데이트되지 않는 이유",
        },
